SELECT d.doc_no AS ref_key, CASE d.status WHEN 'REQ' THEN '결재요청' WHEN 'REV' THEN '결재검토' WHEN 'APV' THEN '결재완료' ELSE d.status END AS target FROM tbl_document d WHERE d.co_cd = #{coCd} AND d.tmpl_cd = 'CCP_COLD' AND d.del_yn = 'N' AND d.status NOT IN ('TMP', 'RJT') AND d.idx IN
#{id}
ORDER BY d.doc_no LIMIT 1

